#!/bin/sh
# Root-reviewed source overlay ONLY, no Cargo/target cleanup.
set -eu
umask 077
cd "$HOME/code/airk"
"$PWD/artifacts/tools/neo-python-3.13.18/bin/python3.13" -I -B - <<'PY'
import base64,hashlib,json,os,subprocess,sys
from pathlib import Path
root=Path.cwd().resolve();assert os.path.samefile(root,Path.home()/'code/airk')
payload=json.loads(base64.b64decode(''))
out=root/'artifacts/advanced-split/receipts/mac-current-read-helpers-r14'
out.mkdir(mode=0o700,exist_ok=False)
for name,row in payload.items():
 assert '/' not in name and name not in ('.','..')
 raw=base64.b64decode(row['base64']);assert hashlib.sha256(raw).hexdigest()==row['sha256']
 with (out/name).open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
env=dict(os.environ);env['AIRK_PUBLIC_SYNC_BATON']='mac-current-read-2cf82d64750bf2a9'
argv=[sys.executable,'-I','-B',str(out/'apply-source.py'),str(out/'plan.json'),str(out/'source.json'),str(out/'public-delta.tar.gz'),payload['plan.json']['sha256'],payload['source.json']['sha256'],payload['public-delta.tar.gz']['sha256']]
raise SystemExit(subprocess.run(argv,env=env,cwd=root).returncode)
PY
